<?php declare(strict_types=1);?>
<section class="catalogue-hero"><div class="container"><p class="rule-label">Order tracking</p><h1><?=e($order['order_no'])?></h1><p>Status: <strong><?=e($order['status'])?></strong></p></div></section>
<section class="container section-space order-detail"><div><h2>Tracking timeline</h2><ol class="timeline"><?php foreach($order['events']as$event):?><li><strong><?=e($event['status'])?></strong><span><?=e(date('d M Y, h:i A',strtotime($event['created_at'].' UTC')))?> IST</span><?php if($event['note']):?><p><?=e($event['note'])?></p><?php endif;?></li><?php endforeach;?></ol></div><aside class="order-summary"><h2>Items</h2><?php foreach($order['items']as$item):?><div class="summary-line"><span><?=e($item['name'])?> × <?=e($item['quantity'])?></span><b><?=money((float)$item['price']*(int)$item['quantity'])?></b></div><?php endforeach;?><dl><div class="summary-total"><dt>Total</dt><dd><?=money($order['total'])?></dd></div></dl><p><?=e($order['address'])?> · <?=e($order['pincode'])?></p><?php if($order['tracking_id']):?><p>Courier: <?=e($order['courier'])?><br>Tracking: <?=e($order['tracking_id'])?></p><?php endif;?></aside></section>
